query:
query ActiveGoogleChannelFeedback($after:String) {
  products(first:250, after:$after, query:"status:active") {
    nodes { id title status feedback { summary details { app { id title } feedbackGeneratedAt state messages { message } link { label url } } } }
    pageInfo { hasNextPage endCursor }
  }
}

canary_query:
query GoogleFeedbackBindingAndSavedAgeGroup($ids: [ID!]!) {
  nodes(ids: $ids) { ... on Product {
    id title
    feedback { summary details { app { id title } feedbackGeneratedAt state link { label url } messages { message } } }
    savedProductAgeGroup: metafield(namespace:"mm-google-shopping",key:"age_group") { type jsonValue updatedAt }
    variants(first:100) { nodes { id title savedVariantAgeGroup: metafield(namespace:"mm-google-shopping",key:"age_group") { type jsonValue updatedAt } } pageInfo { hasNextPage } }
  } }
}
